import AppKit

/// Polls NSPasteboard and reports new items. Our own writes are skipped via `ignoreCurrentChange()`.
public final class ClipboardMonitor {
    public var onItem: ((ClipItem, Data?) -> Void)?
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    private static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ]

    public init() {}

    public func start() {
        timer?.invalidate()
        timer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
    }

    public func stop() { timer?.invalidate(); timer = nil }

    public func ignoreCurrentChange() { lastChange = NSPasteboard.general.changeCount }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        let types = pb.types ?? []
        if types.contains(where: { Self.skipTypes.contains($0.rawValue) }) { return }
        let front = NSWorkspace.shared.frontmostApplication
        let app = front?.localizedName, bid = front?.bundleIdentifier
        let fileOpts: [NSPasteboard.ReadingOptionKey: Any] = [.urlReadingFileURLsOnly: true]
        if let urls = pb.readObjects(forClasses: [NSURL.self], options: fileOpts) as? [URL], !urls.isEmpty {
            let item = ClipItem(kind: .file, text: urls.map(\.path).joined(separator: "\n"), sourceApp: app, sourceBundleID: bid)
            onItem?(item, nil)
            return
        }

        if let s = pb.string(forType: .string), !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let item = ClipItem(kind: .text, text: s, html: pb.string(forType: .html),
                                rtf: pb.data(forType: .rtf), sourceApp: app, sourceBundleID: bid)
            onItem?(item, nil)
        } else if let png = Self.pngData(from: pb) {
            let item = ClipItem(kind: .image, imageKey: ClipItem.sha(png), sourceApp: app, sourceBundleID: bid)
            onItem?(item, png)
        }
    }

    private static func pngData(from pb: NSPasteboard) -> Data? {
        if let d = pb.data(forType: .png) { return d }
        if let t = pb.data(forType: .tiff), let rep = NSBitmapImageRep(data: t) {
            return rep.representation(using: .png, properties: [:])
        }
        return nil
    }
}

public enum PasteboardWriter {
    /// Write an item back to the system pasteboard. `plain` drops rich flavors.
    public static func write(_ item: ClipItem, plain: Bool = false, store: HistoryStore, monitor: ClipboardMonitor?) {
        let pb = NSPasteboard.general
        pb.clearContents()
        switch item.kind {
        case .text:
            pb.setString(item.text ?? "", forType: .string)
            if !plain {
                if let r = item.rtf { pb.setData(r, forType: .rtf) }
                if let h = item.html { pb.setString(h, forType: .html) }
            }
        case .file:
            let urls = item.filePaths.map { URL(fileURLWithPath: $0) as NSURL }
            pb.writeObjects(urls)
        case .image:
            if let d = store.imageData(for: item) { pb.setData(d, forType: .png) }
        }
        monitor?.ignoreCurrentChange()
    }
}
